using Azure.Storage.Blobs;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
namespace RaceDay.Api.Controllers;
[ApiController][Authorize][Route("api/uploads")]
public class UploadsController(IConfiguration configuration, IWebHostEnvironment environment):ControllerBase {
 [HttpPost("event-banner")] public Task<IActionResult> EventBanner(IFormFile file)=>Upload(file,"event-banners");
 [HttpPost("profile-picture")] public Task<IActionResult> ProfilePicture(IFormFile file)=>Upload(file,"profile-pictures");
 async Task<IActionResult> Upload(IFormFile file,string container){if(file==null||file.Length==0)return BadRequest(new{message="Please select an image."});if(file.Length>5*1024*1024)return BadRequest(new{message="Image must be 5 MB or smaller."});var allowed=new[]{"image/jpeg","image/png","image/webp"};if(!allowed.Contains(file.ContentType))return BadRequest(new{message="Only JPG, PNG and WEBP images are allowed."});var connection=configuration.GetConnectionString("AzureBlobStorage");if(string.IsNullOrWhiteSpace(connection))return StatusCode(503,new{message="Azure Blob Storage is not configured. Set ConnectionStrings:AzureBlobStorage."});var service=new BlobServiceClient(connection);var client=service.GetBlobContainerClient(container);await client.CreateIfNotExistsAsync(Azure.Storage.Blobs.Models.PublicAccessType.Blob);var extension=file.ContentType switch { "image/jpeg"=>".jpg", "image/png"=>".png", "image/webp"=>".webp", _=>throw new InvalidOperationException("Unsupported image type.") };var name=$"{Guid.NewGuid():N}{extension}";var blob=client.GetBlobClient(name);await using var stream=file.OpenReadStream();await blob.UploadAsync(stream,new Azure.Storage.Blobs.Models.BlobHttpHeaders{ContentType=file.ContentType});return Ok(new{url=blob.Uri.ToString(),fileName=name,container});}
}
